<script setup>
import {computed,onBeforeUnmount,ref,watch} from 'vue'
import {incidentRequirements} from '../../data/reportingRequirements.js'
import {applyIncidentWeatherSuggestions,createIncidentWeatherLookup,ensureIncidentEnvironment,incidentWeatherIssue,isBlankValue,weatherRequestKey,WEATHER_DOCUMENTATION,MARINE_DOCUMENTATION} from '../../data/incidentWeather.js'
const props=defineProps({model:{type:Object,required:true}})
const requiredEnvironmentFields=new Set(incidentRequirements({vessels:[],environment:{}},{stage:'review'}).filter(item=>item.key.startsWith('environment.')).map(item=>item.key.split('.').at(-1)))
const environmentLabel=(key,label)=>requiredEnvironmentFields.has(key)?`${label} *`:label
watch(()=>props.model.environment,()=>ensureIncidentEnvironment(props.model),{immediate:true})
const environment=computed(()=>props.model.environment),loading=ref(false),error=ref(''),notice=ref(''),session=createIncidentWeatherLookup()
let requestVersion=0
const key=computed(()=>weatherRequestKey(props.model)),issue=computed(()=>incidentWeatherIssue(props.model)),lookup=computed(()=>environment.value.lookup),current=computed(()=>Boolean(lookup.value?.request?.key===key.value))
const suggestionLabels={waveHeightM:'Wave Height (m)',windForce:'Wind Force (Beaufort Scale)',visibility:'Visibility',weatherDescription:'Weather Condition'}
const applicable=computed(()=>current.value?Object.keys(suggestionLabels).filter(field=>isBlankValue(environment.value[field])&&!isBlankValue(lookup.value.suggestions?.[field])):[])
watch(key,()=>{requestVersion++;session.invalidate();loading.value=false;if(lookup.value||notice.value)notice.value='The incident time or position changed. Look up conditions again to use matching suggestions.';error.value=''})
async function lookupConditions(){const ticket=++requestVersion;loading.value=true;error.value='';notice.value='';try{const result=await session.run(props.model);if(ticket!==requestVersion||!result)return;environment.value.lookup=result;notice.value=result.status==='unavailable'?'No model values were available. Your entered conditions are unchanged.':'Suggestions are ready to review. Your entered conditions are unchanged.'}catch(failure){if(ticket===requestVersion)error.value=failure.message||'Lookup failed. You can enter conditions manually.'}finally{if(ticket===requestVersion)loading.value=false}}
function applySuggestions(){error.value='';try{const fields=applyIncidentWeatherSuggestions(props.model,lookup.value);notice.value=fields.length?`Applied ${fields.length} suggestion(s) to blank fields. Existing values were kept.`:'No blank fields need these suggestions.'}catch(failure){error.value=failure.message}}
function markEntered(field){delete environment.value.fieldSources[field]}
function providerUrl(value){try{const url=new URL(value);return url.protocol==='https:'&&['api.open-meteo.com','marine-api.open-meteo.com','historical-forecast-api.open-meteo.com'].includes(url.hostname)?url.href:undefined}catch{return undefined}}
const nonNegative=value=>isBlankValue(value)||(Number.isFinite(Number(value))&&Number(value)>=0)||'Enter zero or more, or leave blank if unknown.'
const windRule=value=>isBlankValue(value)||(Number.isInteger(Number(value))&&Number(value)>=0&&Number(value)<=12)||'Enter a whole Beaufort force from 0 to 12, or leave blank.'
onBeforeUnmount(()=>{requestVersion++;session.invalidate()})
</script>
<template><section class="incident-environment">
 <div class="section-label q-mb-xs">Environmental Conditions</div><p class="text-caption text-blue-grey-6 q-mb-md">Required environmental particulars are completed before validation, or explained as unknown where allowed. Drafts can be saved at any time. Blank values remain unknown; zero is valid.</p>
 <div class="form-grid"><q-input v-model.number="environment.waveHeightM" @update:model-value="markEntered('waveHeightM')" outlined dense type="number" min="0" step="any" :label="environmentLabel('waveHeightM','Wave Height (m)')" :rules="[nonNegative]"/><q-input v-model.number="environment.windForce" @update:model-value="markEntered('windForce')" outlined dense type="number" min="0" max="12" step="1" :label="environmentLabel('windForce','Wind Force (Beaufort Scale)')" :rules="[windRule]"/><q-input v-model="environment.visibility" @update:model-value="markEntered('visibility')" outlined dense :label="environmentLabel('visibility','Visibility')" hint="Reported distance or description"/><q-input v-model="environment.weatherDescription" @update:model-value="markEntered('weatherDescription')" outlined dense :label="environmentLabel('weatherDescription','Weather Condition')"/><q-input v-model="environment.seaState" @update:model-value="markEntered('seaState')" outlined dense :label="environmentLabel('seaState','Sea Condition')"/><q-input v-model="environment.currentTide" @update:model-value="markEntered('currentTide')" outlined dense :label="environmentLabel('currentTide','Current / Tide')"/><q-input v-model="environment.observedAt" @update:model-value="markEntered('observedAt')" outlined dense type="datetime-local" stack-label :label="environmentLabel('observedAt','Environmental Observation Date/Time')" hint="Reported observation time, when known; separate from the lookup hour."/><q-input v-model="environment.source" @update:model-value="markEntered('source')" outlined dense :label="environmentLabel('source','Source of Environmental Information')"/></div>
 <q-expansion-item class="lookup-panel q-mt-md" icon="cloud" label="Look up weather and sea conditions" caption="Optional modelled context from Open-Meteo" default-opened>
 <div class="q-pa-md"><q-banner dense class="context-note q-mb-md">Modelled context is not observed evidence. Suggestions stay separate until you choose to apply them to blank fields.</q-banner><p class="text-caption text-blue-grey-6">Uses the entered occurrence date, time (Asia/Manila) and coordinates. Sea state, current/tide and observation time stay as entered.</p>
 <div class="row items-center q-gutter-sm"><q-btn unelevated color="primary" no-caps icon="cloud_download" label="Look up conditions" :loading="loading" :disable="Boolean(issue)" @click="lookupConditions"/><span v-if="issue" class="text-caption text-blue-grey-6">{{issue}}</span></div>
 <q-banner v-if="error" dense class="bg-red-1 text-negative q-mt-md" role="alert">{{error}}</q-banner><p v-if="notice" class="text-caption q-mt-md q-mb-none" role="status">{{notice}}</p>
 <template v-if="lookup"><q-banner v-if="!current" dense class="bg-orange-1 text-dark q-mt-md">These suggestions belong to a different incident time or position. Look up conditions again before applying them.</q-banner><q-banner v-for="failure in lookup.errors||[]" :key="failure.service" dense class="bg-orange-1 text-dark q-mt-sm" role="alert">{{failure.service==='marine'?'Sea conditions':'Weather'}}: {{failure.message}}</q-banner>
 <div class="suggestion-grid q-mt-md"><div v-for="(label,field) in suggestionLabels" :key="field" class="suggestion-item"><div class="text-caption text-blue-grey-6">{{label}}</div><strong>{{isBlankValue(lookup.suggestions?.[field])?'Not returned':lookup.suggestions[field]}}</strong></div></div>
 <q-btn class="q-mt-md" outline color="primary" no-caps label="Apply suggestions to blank fields" :disable="!current||!applicable.length||loading" @click="applySuggestions"/>
 <q-expansion-item class="q-mt-md" label="Lookup source and time" icon="info_outline"><div class="text-caption provenance q-pa-sm"><p>{{lookup.kind}} · {{lookup.request?.mode==='historical_forecast'?'Historical forecast mode':'Recent forecast mode'}}</p><p>Requested: {{lookup.request?.localDateTime}} Asia/Manila · position {{lookup.request?.lat}}, {{lookup.request?.lon}}</p><p>Lookup sent {{lookup.request?.requestedAt}} · received {{lookup.returnedAt}}</p><div v-for="(response,service) in lookup.responses||{}" :key="service" class="q-mb-sm"><strong>{{service==='marine'?'Sea conditions':'Weather'}}</strong><template v-if="response.ok"><div>Model hour: {{response.matchedTime}} (UTC)</div><div>Returned grid position: {{response.returnedLocation?.lat??'Unknown'}}, {{response.returnedLocation?.lon??'Unknown'}}</div></template><div v-else>{{response.error}}</div><a v-if="providerUrl(response.url)" :href="providerUrl(response.url)" target="_blank" rel="noopener noreferrer">Open provider request</a></div><p v-if="lookup.appliedAt">Applied {{lookup.appliedAt}} · {{lookup.appliedFields?.join(', ')}}</p></div></q-expansion-item>
 </template><div class="text-caption text-blue-grey-6 q-mt-md">Data: <a :href="WEATHER_DOCUMENTATION" target="_blank" rel="noopener noreferrer">Open-Meteo weather</a> · <a :href="MARINE_DOCUMENTATION" target="_blank" rel="noopener noreferrer">Marine models</a> · CC BY 4.0. Beaufort suggestions are estimates from modelled 10 m wind.</div>
 </div></q-expansion-item>
</section></template>
<style scoped>
.incident-environment{font-family:'Hanken Grotesk',sans-serif}.section-label{color:#002147;font-size:15px;font-weight:700}.lookup-panel{background:#fff;border:1px solid #e2e8f0;border-radius:8px}.context-note{background:#eff6ff;color:#1e3a5f;border:1px solid #bfdbff;border-radius:8px}.suggestion-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.suggestion-item{padding:10px 12px;border:1px solid #e2e8f0;background:#f8fafc;border-radius:8px}.provenance{overflow-wrap:anywhere}:deep(.q-field--outlined .q-field__control){border-radius:8px;background:#fff}:deep(.q-field--outlined .q-field__control:before){border-color:#cbd5e1}:deep(.q-field--outlined.q-field--focused .q-field__control:after){border-color:#002147}@media(max-width:599px){.suggestion-grid{grid-template-columns:1fr}}:global(.body--dark) .section-label{color:#cbd5e1}:global(.body--dark) .incident-environment :deep(.q-field--outlined .q-field__control),:global(.body--dark) .lookup-panel{background:#0f172a}:global(.body--dark) .suggestion-item{background:#1e293b;border-color:#334155}
</style>
